sqlEquivalent:
CREATE TABLE lab_staff (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  manager_id INTEGER REFERENCES lab_staff(id) ON DELETE SET NULL
);

starterCode:
// JavaScript track — same Prisma DSL
model LabStaff {
  id Int @id @default(autoincrement())
  name String
  managerId Int? @map("manager_id")
  manager LabStaff? @relation("StaffTree", fields: [managerId], references: [id])
  reports LabStaff[] @relation("StaffTree")
  @@map("lab_staff")
}
